$p='C:\Users\dom12\Documents\unity_test_hdrp'; Set-Location $p; $u='C:\Program Files\Unity\Hub\Editor\6000.6.7f1\Editor\Unity.exe'; $to="$p\TestOut"; $log="$to\v109ha_chain.txt"; Remove-Item $log,"$to\v109ha_chain_complete.txt" -EA SilentlyContinue
function Say($m){ Add-Content $log ("{0} {1}" -f (Get-Date -Format 'HH:mm:ss'),$m) }
while(Get-Process Unity -EA SilentlyContinue | ? { (Get-CimInstance Win32_Process -Filter "ProcessId=$($_.Id)").CommandLine -match 'projectPath' }){ Say 'waiting other Editor'; Start-Sleep 15 }
foreach($st in @(@('ClipBuild','CharacterClipBuild.RunBatch'),@('GuardLayer','GuardLayerSetup.Run'))){ Say "$($st[0]) start"; $b=Start-Process $u -ArgumentList "-batchmode -nographics -quit -accept-apiupdate -silent-crashes -projectPath $p -executeMethod $($st[1]) -logFile $to\v109ha_$($st[0]).log" -PassThru; if(-not $b.WaitForExit(1500000)){ $b.Kill() }; Say "$($st[0]) exit $($b.ExitCode)" }
Say 'build start'; & powershell -NoProfile -File "$p\Tools\build_v109ha.ps1"; Say ('build done: ' + (Get-Content "$to\v109ha_done.txt" -EA SilentlyContinue)); Set-Content "$to\v109ha_chain_complete.txt" ((Get-Content "$to\v109ha_done.txt" -EA SilentlyContinue))
